using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using RaceDay.Api.Data;
using RaceDay.Api.Dtos;
using RaceDay.Api.Models;
using RaceDay.Api.Services;
namespace RaceDay.Api.Controllers;
[ApiController]
public class ResultsController(RaceDayDbContext db):ControllerBase
{
    /// <summary>Returns results belonging to the authenticated participant.</summary>
    [Authorize(Roles="Participant"),HttpGet("api/results/me")] public async Task<ActionResult<IEnumerable<ResultResponse>>> Mine()=>Ok(await Query().Where(x=>x.Enrolment!.ParticipantId==User.UserId()).OrderBy(x=>x.RecordedAt).Select(x=>new ResultResponse(x.ResultId,x.EnrolmentId,x.Enrolment!.ParticipantId,$"{x.Enrolment.Participant!.FirstName} {x.Enrolment.Participant.LastName}",x.Enrolment.Category!.EventId,x.Enrolment.Category.Event!.EventName,x.FinishPosition,x.FinishTimeSeconds,x.ResultStatus,x.RecordedAt)).ToListAsync());
    /// <summary>Returns results for an organiser's event.</summary>
    [Authorize(Roles="Organiser"),HttpGet("api/events/{eventId:int}/results")] public async Task<ActionResult<IEnumerable<ResultResponse>>> EventResults(int eventId){var e=await db.Events.FindAsync(eventId);if(e is null)return NotFound();if(e.OrganiserId!=User.UserId())return Forbid();return Ok(await Query().Where(x=>x.Enrolment!.Category!.EventId==eventId).OrderBy(x=>x.FinishPosition).Select(x=>new ResultResponse(x.ResultId,x.EnrolmentId,x.Enrolment!.ParticipantId,$"{x.Enrolment.Participant!.FirstName} {x.Enrolment.Participant.LastName}",x.Enrolment.Category!.EventId,x.Enrolment.Category.Event!.EventName,x.FinishPosition,x.FinishTimeSeconds,x.ResultStatus,x.RecordedAt)).ToListAsync());}
    /// <summary>Records a result for an enrolment in an organiser's event.</summary>
    [Authorize(Roles="Organiser"),HttpPost("api/events/{eventId:int}/results")] public async Task<ActionResult<ResultResponse>> Create(int eventId,ResultRequest request){var e=await db.Events.FindAsync(eventId);if(e is null)return NotFound();if(e.OrganiserId!=User.UserId())return Forbid();var enrol=await db.Enrolments.Include(x=>x.Category).SingleOrDefaultAsync(x=>x.EnrolmentId==request.EnrolmentId);if(enrol is null||enrol.Category!.EventId!=eventId)return BadRequest(new{message="The enrolment does not belong to this event."});if(await db.Results.AnyAsync(x=>x.EnrolmentId==request.EnrolmentId))return Conflict(new{message="A result already exists for this enrolment."});var error=Validate(request);if(error is not null)return BadRequest(new{message=error});var result=new Result{EnrolmentId=request.EnrolmentId,FinishPosition=request.FinishPosition,FinishTimeSeconds=request.FinishTimeSeconds,ResultStatus=request.ResultStatus};db.Results.Add(result);await db.SaveChangesAsync();return Created($"/api/results/{result.ResultId}",await Query().Where(x=>x.ResultId==result.ResultId).Select(x=>new ResultResponse(x.ResultId,x.EnrolmentId,x.Enrolment!.ParticipantId,$"{x.Enrolment.Participant!.FirstName} {x.Enrolment.Participant.LastName}",x.Enrolment.Category!.EventId,x.Enrolment.Category.Event!.EventName,x.FinishPosition,x.FinishTimeSeconds,x.ResultStatus,x.RecordedAt)).SingleAsync());}
    /// <summary>Corrects a result recorded for an organiser's event.</summary>
    [Authorize(Roles="Organiser"),HttpPut("api/results/{id:int}")] public async Task<ActionResult<ResultResponse>> Update(int id,ResultRequest request){var r=await Query().SingleOrDefaultAsync(x=>x.ResultId==id);if(r is null)return NotFound();if(r.Enrolment!.Category!.Event!.OrganiserId!=User.UserId())return Forbid();var error=Validate(request);if(error is not null)return BadRequest(new{message=error});var entity=await db.Results.FindAsync(id);entity!.FinishPosition=request.FinishPosition;entity.FinishTimeSeconds=request.FinishTimeSeconds;entity.ResultStatus=request.ResultStatus;await db.SaveChangesAsync();return Ok(await Query().Where(x=>x.ResultId==id).Select(x=>new ResultResponse(x.ResultId,x.EnrolmentId,x.Enrolment!.ParticipantId,$"{x.Enrolment.Participant!.FirstName} {x.Enrolment.Participant.LastName}",x.Enrolment.Category!.EventId,x.Enrolment.Category.Event!.EventName,x.FinishPosition,x.FinishTimeSeconds,x.ResultStatus,x.RecordedAt)).SingleAsync());}
    /// <summary>Deletes a result recorded for an organiser's event.</summary>
    [Authorize(Roles="Organiser"),HttpDelete("api/results/{id:int}")] public async Task<IActionResult> Delete(int id){var r=await Query().SingleOrDefaultAsync(x=>x.ResultId==id);if(r is null)return NotFound();if(r.Enrolment!.Category!.Event!.OrganiserId!=User.UserId())return Forbid();db.Results.Remove(await db.Results.FindAsync(id) ?? throw new InvalidOperationException());await db.SaveChangesAsync();return NoContent();}
    IQueryable<Result> Query()=>db.Results.AsNoTracking().Include(x=>x.Enrolment).ThenInclude(x=>x!.Participant).Include(x=>x.Enrolment).ThenInclude(x=>x!.Category).ThenInclude(x=>x!.Event);
    static string? Validate(ResultRequest r)=>r.ResultStatus is not("Finished" or "DNF" or "DNS" or "Disqualified")?"Invalid result status.":r.FinishPosition is <=0?"Finish position must be greater than zero.":r.FinishTimeSeconds is <=0?"Finish time must be greater than zero.":null;
    static ResultResponse Map(Result x)=>new(x.ResultId,x.EnrolmentId,x.Enrolment!.ParticipantId,$"{x.Enrolment.Participant!.FirstName} {x.Enrolment.Participant.LastName}",x.Enrolment.Category!.EventId,x.Enrolment.Category.Event!.EventName,x.FinishPosition,x.FinishTimeSeconds,x.ResultStatus,x.RecordedAt);
}
